def make_a_pile_helper(value, levels, stones):
    if levels == 0:
        return stones
    stones.append(value)
    return make_a_pile_helper(value + 2, levels - 1, stones)


def make_a_pile(n):
    return make_a_pile_helper(n, n, [])


assert make_a_pile(1) == [1]
assert make_a_pile(3) == [3, 5, 7]
assert make_a_pile(4) == [4, 6, 8, 10]

